doc = App.getDocument("hook")
sh = doc.Params
for c in sh.getUsedCells() if hasattr(sh,'getUsedCells') else []:
    print(c, sh.getContents(c), sh.get(c) if sh.getContents(c) else None)
print("aliases:", [(a, sh.getCellFromAlias(a)) for a in ['plate_height'] ])
for name in ["HookSketch","HoleSketch"]:
    s = doc.getObject(name)
    print(name, "solve status:", s.solve())
    try: print(" DoF:", s.FullyConstrained, getattr(s,'DoF',None))
    except Exception as e: print(e)
    for i,c in enumerate(s.Constraints):
        print(" ", i, c.Type, c.Name, c.First, c.FirstPos, c.Second, c.SecondPos, c.Value, "driving" if c.Driving else "ref")
    print(" expr:", s.ExpressionEngine)
    print(" malformed/conflicting/redundant:", s.MalformedConstraints, s.ConflictingConstraints, s.RedundantConstraints, s.PartiallyRedundantConstraints)
